25	void AssignDefaultIoIndex(af::AscGraph &graph) {
26	  int32_t data_index = 0;
27	  int32_t output_index = 0;
28	  for (const auto &node : graph.GetAllNodes()) {
29	    if (node->GetType() == "Data") {
30	      auto &attr = reinterpret_cast<af::AscDataIrAttrDef &>(*node->attr.ir_attr);
31	      attr.SetIndex(data_index++);
32	    } else if (node->GetType() == "Output") {
33	      node->attr.ir_attr = af::AscDataIrAttrDef().Clone();
34	      auto &attr = reinterpret_cast<af::AscDataIrAttrDef &>(*node->attr.ir_attr);
35	      attr.SetIndex(output_index++);
36	    } else {
37	    }
38	  }
39	}
