89	int AutofuserOptions::Init(PyObject *self, PyObject *args, PyObject *kwds) {
90	  (void)args;
91	  auto self_ = reinterpret_cast<AutofuserOptions::Object *>(self);
92	
93	  self_->optimizer = new optimize::OptimizerOptions();
94	  self_->codegen = new codegen::CodegenOptions();
95	
96	  if (kwds != nullptr) {
97	    PyObject *tiling_lib_path_kwarg = PyDict_GetItemString(kwds, "tiling_lib_path");
98	    PyObject *tiling_lib_codegen_symbol_kwarg = PyDict_GetItemString(kwds, "tiling_lib_codegen_symbol");
99	
100	    if (tiling_lib_path_kwarg != nullptr && PyUnicode_Check(tiling_lib_path_kwarg)) {
101	      Py_ssize_t tiling_lib_path_len;
102	      const char *tiling_lib_path = PyUnicode_AsUTF8AndSize(tiling_lib_path_kwarg, &tiling_lib_path_len);
103	      self_->codegen->tiling_lib_path = std::string(tiling_lib_path, tiling_lib_path_len);
104	    }
105	
106	    if (tiling_lib_codegen_symbol_kwarg != nullptr && PyUnicode_Check(tiling_lib_codegen_symbol_kwarg)) {
107	      Py_ssize_t tiling_lib_codegen_symbol_len;
108	      const char *tiling_lib_codegen_symbol =
109	          PyUnicode_AsUTF8AndSize(tiling_lib_codegen_symbol_kwarg, &tiling_lib_codegen_symbol_len);
110	      self_->codegen->tiling_lib_codegen_symbol = std::string(tiling_lib_codegen_symbol, tiling_lib_codegen_symbol_len);
111	    }
112	
113	    PyObject *graph_kwarg = PyDict_GetItemString(kwds, "graph_type");
114	    if (graph_kwarg != nullptr && PyLong_Check(graph_kwarg)) {
115	      int64_t graph_type = PyLong_AsLong(graph_kwarg);
116	      self_->optimizer->graph_type = static_cast<optimize::GraphType>(graph_type);
117	    }
118	  }
119	
120	  return 0;
121	}
