188	PyObject *Autofuser::Schedule(PyObject *self, PyObject *args, PyObject *kwds) {
189	  (void)kwds;
190	  ascir::AscGraphDumperContext::GetThreadLocalCtx().ClearAllWatchGraphs();
191	  auto self_ = reinterpret_cast<Autofuser::Object *>(self);
192	
193	  PyObject *graph_obj = nullptr;
194	  if (PyArg_ParseTuple(args, "O", &graph_obj) == kPythonFail) {
195	    return PyErr_Format(PyExc_ValueError, "autofuse input args error");
196	  }
197	
198	  PyObject *fused_schedule_result_obj =
199	      pyascir::FusedScheduledResult::New(&pyascir::FusedScheduledResult::type, nullptr, nullptr);
200	  auto ret_init = pyascir::FusedScheduledResult::Init(fused_schedule_result_obj, nullptr, nullptr);
201	  GE_CHK_BOOL_RET_SPECIAL_STATUS(ret_init != 0, PyErr_Format(PyExc_TypeError, "FusedScheduledResult init fail"),
202	                                 "FusedScheduledResult init fail");
203	  auto fused_schedule_result = reinterpret_cast<pyascir::FusedScheduledResult::Object *>(fused_schedule_result_obj);
204	  if (PyObject_IsInstance(graph_obj, reinterpret_cast<PyObject *>(&pyascir::HintGraph::type)) == kPythonSuccess) {
205	    auto hint_graph = reinterpret_cast<pyascir::HintGraph::Object *>(graph_obj);
206	    PY_ASSERT_NOTNULL(hint_graph->graph);
207	    AssignDefaultIoIndex(*hint_graph->graph);
208	    auto ret = self_->optimizer->Optimize(*(hint_graph->graph), fused_schedule_result->fused_schedule_result);
209	    if (ret != 0) {
210	      ERROR_PRINT("Optimize fail ret %d", ret);
211	      ascir::AscGraphDumperContext::GetThreadLocalCtx().DumpWatchedGraphs();
212	      return PyErr_Format(PyExc_RuntimeError, "Optimize fail");
213	    }
214	    return Py_BuildValue("O", fused_schedule_result_obj);
215	  } else if (PyObject_IsInstance(graph_obj, reinterpret_cast<PyObject *>(&pyascir::FusedGraph::type)) ==
216	             kPythonSuccess) {
217	    auto fused_graph = reinterpret_cast<pyascir::FusedGraph::Object *>(graph_obj);
218	    auto ret = self_->optimizer->Optimize(fused_graph->graph, fused_schedule_result->fused_schedule_result);
219	    if (ret != 0) {
220	      ERROR_PRINT("Optimize fail ret %d", ret);
221	      ascir::AscGraphDumperContext::GetThreadLocalCtx().DumpWatchedGraphs();
222	      return PyErr_Format(PyExc_RuntimeError, "Optimize fail");
223	    }
224	    return Py_BuildValue("O", fused_schedule_result_obj);
225	  } else {
226	    return PyErr_Format(PyExc_RuntimeError, "schedule requires hint graph or fused graph");
227	  }
228	}
