253	PyObject *Autofuser::AutofuseBackend(PyObject *self, PyObject *args, PyObject *kwds) {
254	  (void)kwds;
255	  auto self_ = reinterpret_cast<Autofuser::Object *>(self);
256	
257	  PyObject *graph_obj = nullptr;
258	  if (PyArg_ParseTuple(args, "O", &graph_obj) == kPythonFail) {
259	    return PyErr_Format(PyExc_ValueError, "autofuse input args error");
260	  }
261	
262	  ascir::FusedScheduledResult fused_schedule_result;
263	
264	  if (PyObject_IsInstance(graph_obj, reinterpret_cast<PyObject *>(&pyascir::HintGraph::type)) == kPythonSuccess) {
265	    auto hint_graph = reinterpret_cast<pyascir::HintGraph::Object *>(graph_obj);
266	    PY_ASSERT_NOTNULL(hint_graph->graph);
267	    AssignDefaultIoIndex(*hint_graph->graph);
268	    auto ret = self_->optimizer->Optimize(*(hint_graph->graph), fused_schedule_result);
269	    if (ret != 0) {
270	      ERROR_PRINT("Optimize fail ret %d", ret);
271	      return PyErr_Format(PyExc_RuntimeError, "Optimize fail");
272	    }
273	  } else if (PyObject_IsInstance(graph_obj, reinterpret_cast<PyObject *>(&pyascir::FusedGraph::type)) ==
274	             kPythonSuccess) {
275	    auto fused_graph = reinterpret_cast<pyascir::FusedGraph::Object *>(graph_obj);
276	    auto ret = self_->optimizer->Optimize(fused_graph->graph, fused_schedule_result);
277	    if (ret != 0) {
278	      ERROR_PRINT("Optimize fail ret %d", ret);
279	      return PyErr_Format(PyExc_RuntimeError, "Optimize fail");
280	    }
281	  } else {
282	    return PyErr_Format(PyExc_RuntimeError, "schedule requires hint graph or fused graph");
283	  }
284	
285	  codegen::CodegenResult result;
286	  try {
287	    if (self_->codegen->GenerateForInductor(fused_schedule_result, result) != af::SUCCESS) {
288	      GELOGE(af::FAILED, "Codegen generate kernel failed");
289	    }
290	  } catch (const std::runtime_error &e) {
291	    GELOGE(af::FAILED, "Caught a runtime_error: %s", e.what());
292	  }
293	
294	  return Py_BuildValue("sss", result.tiling_data.c_str(), result.tiling.c_str(), result.kernel.c_str());
295	}
