567	af::Status CodeGen::HandleHostCodeGenForCVFusion(CodeGen::Object *self,
568	                                                 const ascir::FusedScheduledResult &fused_schedule_result,
569	                                                 const std::map<std::string, std::string> &symbol_source_info,
570	                                                 const char *pgo_dir, const char *vector_core_num,
571	                                                 PyObject *py_tilings) {
572	  ascir::FusedScheduledResult ub_schedule_result = fused_schedule_result;
573	  ascir::FusedScheduledResult common_schedule_result = fused_schedule_result;
574	
575	  GE_ASSERT_SUCCESS(ascgen_utils::FilterCVFusionUBResult(ub_schedule_result));
576	  GE_ASSERT_SUCCESS(ascgen_utils::FilterCVFusionCommonResult(common_schedule_result));
577	
578	  // 生成UB模板的代码,存在没有UB模板的场景
579	  std::map<std::string, std::string> ub_tiling_file_name_to_content;
580	  if (ascgen_utils::HasCubeUBFusedScheduled(ub_schedule_result)) {
581	    GE_CHK_STATUS_RET(self->codegen->GenerateTiling(ub_schedule_result, symbol_source_info, pgo_dir, vector_core_num,
582	                                                    ub_tiling_file_name_to_content),
583	                      "generate ub tiling failed");
584	  } else {
585	    GELOGI("Has no cube ub fused schedule result, no need to generate ub tiling");
586	  }
587	
588	  // 生成兜底模板的代码，必须有兜底模板
589	  GE_ASSERT_TRUE(ascgen_utils::HasCubeCommonFusedScheduled(common_schedule_result));
590	  std::map<std::string, std::string> common_tiling_file_name_to_content;
591	  GE_CHK_STATUS_RET(self->codegen->GenerateTiling(common_schedule_result, symbol_source_info, pgo_dir, vector_core_num,
592	                                                  common_tiling_file_name_to_content),
593	                    "generate common tiling failed");
594	
595	  // 创建UB模板、兜底模板的内层字典
596	  PyObject *ub_dict = PyDict_New();
597	  if (ub_dict == nullptr) {
598	    return af::FAILED;
599	  }
600	  GE_DISMISSABLE_GUARD(ub_dict_guard, [ub_dict]() { Py_DECREF(ub_dict); });
601	
602	  PyObject *common_dict = PyDict_New();
603	  if (common_dict == nullptr) {
604	    return af::FAILED;
605	  }
606	  GE_DISMISSABLE_GUARD(common_dict_guard, [common_dict]() { Py_DECREF(common_dict); });
607	
608	  // 将UB模板的结果添加到内层字典中
609	  for (const auto &[key, value] : ub_tiling_file_name_to_content) {
610	    PyObjectGuard tmp_guard(PyUnicode_FromString(value.c_str()));
611	    PyDict_SetItemString(ub_dict, key.c_str(), tmp_guard.get());
612	  }
613	
614	  // 将兜底模板的结果添加到内层字典中
615	  for (const auto &[key, value] : common_tiling_file_name_to_content) {
616	    PyObjectGuard tmp_guard(PyUnicode_FromString(value.c_str()));
617	    PyDict_SetItemString(common_dict, key.c_str(), tmp_guard.get());
618	  }
619	
620	  // 将内层字典添加到外层字典中
621	  PyDict_SetItemString(py_tilings, "ub", ub_dict);
622	  PyDict_SetItemString(py_tilings, "common", common_dict);
623	
624	  // 释放内层字典的所有权，因为外层字典已经持有引用
625	  GE_DISMISS_GUARD(ub_dict_guard);
626	  GE_DISMISS_GUARD(common_dict_guard);
627	
628	  return af::SUCCESS;
629	}
