764	PyObject *CodeGen::host_code_generator(PyObject *self_pyobject, PyObject *args, PyObject *kwds) {
765	  (void)kwds;
766	  auto self = reinterpret_cast<CodeGen::Object *>(self_pyobject);
767	
768	  PyObject *list_result_result = nullptr;
769	  PyObject *shape_info_obj = nullptr;
770	  PyObject *output_shape_obj = nullptr;
771	  const char *pgo_dir = nullptr;
772	  const char *vector_core_num = "";
773	  if (PyArg_ParseTuple(args, "OOOss", &list_result_result, &shape_info_obj, &output_shape_obj, &pgo_dir,
774	                       &vector_core_num) == kPythonFail) {
775	    return PyErr_Format(PyExc_ValueError, "codegen param parse failed");
776	  }
777	
778	  if (shape_info_obj == Py_None) {
779	    GELOGW("host_code_generator shape info is none");
780	  } else if (PyObject_IsInstance(shape_info_obj, reinterpret_cast<PyObject *>(&pyascir::ShapeInfo::type)) ==
781	             kPythonFail) {
782	    return PyErr_Format(PyExc_ValueError, "host_code_generator shape info type invalid");
783	  }
784	
785	  if (PyObject_IsInstance(list_result_result, reinterpret_cast<PyObject *>(&pyascir::FusedScheduledResult::type)) !=
786	      kPythonSuccess) {
787	    return PyErr_Format(PyExc_TypeError, "host_code_generator requires FusedScheduledResult");
788	  }
789	  auto fused_schedule_result = reinterpret_cast<pyascir::FusedScheduledResult::Object *>(list_result_result);
