903	PyMODINIT_FUNC PyInit_pyautofuse(void) {
904	  pyautofuse_type_init();
905	  pyascir_type_init();
906	  pyascir_types_type_init();
907	
908	  auto pyautofuse_module = PyModule_Create(&PyAutofuseModule);
909	  PY_ASSERT_NOTNULL(pyautofuse_module);
910	
911	  auto pyascir_module = PyInit_ascir();
912	  if (pyascir_module == nullptr) {
913	    Py_DECREF(pyautofuse_module);
914	    return nullptr;
915	  }
916	  PyModule_AddObject(pyautofuse_module, "ascir", pyascir_module);
917	
918	  if (PyType_Ready(&pyascir::AutofuserOptions::type) < 0) {
919	    Py_DECREF(pyautofuse_module);
920	    Py_DECREF(pyascir_module);
921	    return nullptr;
922	  };
923	  PyModule_AddObject(pyautofuse_module, "AutofuserOptions",
924	                     reinterpret_cast<PyObject *>(&pyascir::AutofuserOptions::type));
925	
926	  if (PyType_Ready(&pyascir::Autofuser::type) < 0) {
927	    Py_DECREF(pyautofuse_module);
928	    Py_DECREF(pyascir_module);
929	    return nullptr;
930	  }
931	  PyModule_AddObject(pyautofuse_module, "Autofuser", reinterpret_cast<PyObject *>(&pyascir::Autofuser::type));
932	
933	  if (PyType_Ready(&pyascir::Schedule::type) < 0) {
934	    Py_DECREF(pyautofuse_module);
935	    Py_DECREF(pyascir_module);
936	    return nullptr;
937	  }
938	  PyModule_AddObject(pyautofuse_module, "Schedule", reinterpret_cast<PyObject *>(&pyascir::Schedule::type));
939	
940	  if (PyType_Ready(&pyascir::CodeGen::type) < 0) {
941	    Py_DECREF(pyautofuse_module);
942	    Py_DECREF(pyascir_module);
943	    return nullptr;
944	  }
945	  PyModule_AddObject(pyautofuse_module, "CodeGen", reinterpret_cast<PyObject *>(&pyascir::CodeGen::type));
946	
947	  // Register ascir as a top-level module in sys.modules
948	  // This allows "from ascir import Max, Min, Mod" to work directly
949	  PyObject *modules = PyImport_GetModuleDict();
950	  Py_INCREF(pyascir_module);
951	  PyDict_SetItem(modules, PyUnicode_FromString("ascir"), pyascir_module);
952	
953	  // Register pyautofuse as "autofuse.pyautofuse" in sys.modules
954	  Py_INCREF(pyautofuse_module);
955	  PyDict_SetItem(modules, PyUnicode_FromString("autofuse.pyautofuse"), pyautofuse_module);
956	
957	  return pyautofuse_module;
958	}
