64	Status FinalizeIndexedGraphs(std::vector<ascir::ScheduledResult> &scheduled_results) {
65	  for (size_t result_idx = 0UL; result_idx < scheduled_results.size(); ++result_idx) {
66	    auto &scheduled_result = scheduled_results[result_idx];
67	    for (size_t group_idx = 0UL; group_idx < scheduled_result.schedule_groups.size(); ++group_idx) {
68	      auto &schedule_group = scheduled_result.schedule_groups[group_idx];
69	      for (size_t impl_idx = 0UL; impl_idx < schedule_group.impl_graphs.size(); ++impl_idx) {
