75	        GE_ASSERT_NOTNULL(compute_graph);
76	        compute_graph->SetName(new_name);
77	        GELOGD("Rename graph: [%s] -> [%s]", old_name.c_str(), new_name.c_str());
78	
79	        // 如果有 score func，直接在 map 中更新 key（只查找一次）
80	        auto node = schedule_group.graph_name_to_score_funcs.extract(old_name);
81	        if (!node.empty()) {
82	          node.key() = std::move(new_name);
83	          schedule_group.graph_name_to_score_funcs.insert(std::move(node));
84	          GELOGD("Update score func key: [%s] -> [%s]", old_name.c_str(), node.key().c_str());
