92	bool IsAxisContinuous(const af::AscGraph &graph, const int64_t pre_id_idx, const int64_t post_id_idx) {
93	  for (const auto &node : graph.GetAllNodes()) {
94	    if (ScheduleUtils::IsBuffer(node)) {
95	      continue;
96	    }
97	    auto pre_id = node->attr.sched.axis[pre_id_idx];
98	    auto post_id = node->attr.sched.axis[post_id_idx];
99	    for (auto &out_tensor : node->outputs()) {
100	      auto pre_iter = std::find(out_tensor->attr.axis.begin(), out_tensor->attr.axis.end(), pre_id);
101	      auto post_iter = std::find(out_tensor->attr.axis.begin(), out_tensor->attr.axis.end(), post_id);
102	      if ((pre_iter == out_tensor->attr.axis.end()) || (post_iter == out_tensor->attr.axis.end())) {
103	        return false;
104	      }
105	      auto pre_idx = std::distance(out_tensor->attr.axis.begin(), pre_iter);
106	      auto post_idx = std::distance(out_tensor->attr.axis.begin(), post_iter);
107	      auto post_stride = out_tensor->attr.strides[post_idx] * out_tensor->attr.repeats[post_idx];
108	      if ((pre_idx + 1 != post_idx) ||
109	          (af::SymbolicUtils::StaticCheckEq(out_tensor->attr.strides[pre_idx], post_stride) != af::TriBool::kTrue)) {
110	        return false;
111	      }
112	    }
113	  }
114	  return true;
115	}
