117	std::vector<std::vector<int64_t>> MergeContinuousPairs(const std::vector<std::pair<int64_t, int64_t>> &potential_axis) {
118	  std::vector<std::vector<int64_t>> continuous_ids;
119	  if (potential_axis.empty()) {
120	    return continuous_ids;
121	  }
122	
123	  std::vector<int64_t> current_chain;
124	  current_chain.push_back(potential_axis[0].first);
125	  current_chain.push_back(potential_axis[0].second);
126	
127	  for (size_t i = 1UL; i < potential_axis.size(); ++i) {
128	    const auto &cur_pair = potential_axis[i];
129	    if (current_chain.back() == cur_pair.first) {
130	      current_chain.push_back(cur_pair.second);
131	    } else {
132	      continuous_ids.push_back(current_chain);
133	      current_chain.clear();
134	      current_chain.push_back(cur_pair.first);
135	      current_chain.push_back(cur_pair.second);
136	    }
137	  }
138	  continuous_ids.push_back(current_chain);
139	
140	  return continuous_ids;
141	}
