143	std::unordered_set<size_t> IdentifyZeroStrideAxisIndices(const ascir::ImplGraph &owner_graph) {
144	  std::vector<bool> is_zero_stride_axis;
145	  bool include_reduce = false;
146	  for (const auto &node : owner_graph.GetAllNodes()) {
147	    GE_ASSERT_NOTNULL(node);
148	    if (!ScheduleUtils::IsBuffer(node) && is_zero_stride_axis.empty()) {
149	      is_zero_stride_axis.resize(node->attr.sched.axis.size(), true);
150	    }
151	    if (ScheduleUtils::IsReduce(node)) {
152	      include_reduce = true;
153	    }
154	  }
155	
156	  for (const auto &node : owner_graph.GetAllNodes()) {
157	    GE_ASSERT_NOTNULL(node);
158	    if (ScheduleUtils::IsBuffer(node)) {
159	      continue;
160	    }
161	
162	    // 当前节点包含_keep_first_axis属性且为true，或者图上包含reduce节点时，需要保留首轴
163	    bool keep_first_axis = false;
164	    (void)af::AttrUtils::GetBool(node->GetOpDesc(), "_keep_first_axis", keep_first_axis);
165	    keep_first_axis = keep_first_axis || include_reduce;
166	
167	    const auto &loop_axes = node->attr.sched.axis;
168	    for (size_t loop_idx = 0UL; loop_idx < loop_axes.size(); ++loop_idx) {
169	      bool has_non_zero_stride = false;
170	      for (const auto &output : node->outputs()) {
171	        auto iter = std::find(output->attr.axis.begin(), output->attr.axis.end(), loop_axes[loop_idx]);
172	        GE_ASSERT_TRUE(iter != output->attr.axis.end());
173	
174	        auto axis_index = static_cast<size_t>(std::distance(output->attr.axis.begin(), iter));
175	        GE_ASSERT_TRUE(axis_index < output->attr.strides.size(), "axis index [%zu] is out of range, max_size:[%zu].",
176	                       axis_index, output->attr.strides.size());
177	
178	        if (af::SymbolicUtils::StaticCheckEq(output->attr.strides[axis_index], af::sym::kSymbolZero) !=
179	                af::TriBool::kTrue ||
180	            (keep_first_axis && (axis_index == 0))) {
181	          has_non_zero_stride = true;
182	          break;
183	        }
184	      }
185	
186	      if (has_non_zero_stride) {
187	        is_zero_stride_axis[loop_idx] = false;
188	      }
189	    }
190	  }
191	
192	  std::unordered_set<size_t> zero_stride_axis_indices;
193	  for (size_t i = 0UL; i < is_zero_stride_axis.size(); ++i) {
194	    if (is_zero_stride_axis[i]) {
195	      zero_stride_axis_indices.emplace(i);
196	    }
197	  }
198	  // 全0场景,不需要删除
199	  if (zero_stride_axis_indices.size() == is_zero_stride_axis.size()) {
200	    return {};
201	  }
202	
203	  return zero_stride_axis_indices;
204	}
