206	Status GetDirectFatherNode(const af::AscGraph &impl_graph, std::map<int64_t, int64_t> &dir_father_nodes) {
207	  for (const auto &node : impl_graph.GetAllNodes()) {
208	    GE_CHECK_NOTNULL(node);
209	    GE_CHECK_NOTNULL(node->GetOpDesc());
210	    for (const auto &out_node : node->GetOutAllNodes()) {
211	      GE_CHECK_NOTNULL(out_node);
212	      GE_CHECK_NOTNULL(out_node->GetOpDesc());
213	      // 若输出节点为store或output，则认为其父节点即自己，否则所有节点的公共父节点都会搜索到store->output节点，保证并查集能够搜索到两个节点的公共计算节点。
214	      if (af::ops::IsOps<Store>(out_node) || af::ops::IsOps<Output>(out_node)) {
215	        dir_father_nodes.insert(std::make_pair(node->GetOpDesc()->GetId(), node->GetOpDesc()->GetId()));
216	        continue;
217	      }
218	      dir_father_nodes.insert(std::make_pair(node->GetOpDesc()->GetId(), out_node->GetOpDesc()->GetId()));
219	    }
220	  }
221	  return af::SUCCESS;
222	}
