255	Status SearchNodesNeedForward(const af::AscGraph &impl_graph, std::map<int64_t, int64_t> &need_forward_nodes_id,
256	                              int64_t &first_load_id) {
257	  std::map<int64_t, int64_t> dir_father_nodes;  // 以节点id形式存储所有节点的直接父节点
258	  GE_ASSERT_SUCCESS(GetDirectFatherNode(impl_graph, dir_father_nodes));
259	  constexpr size_t load_thresh = 2UL;    // 能够参与调序的load节点个数阈值
260	  size_t num_of_load_need_adjust = 0UL;  // 用于记录需要调序的load节点个数，判断是否达到阈值
261	  size_t index_data_and_load = 0UL;
262	  std::map<int64_t, vector<int64_t>> loads_with_same_queid;  // 获取TQue的共复用情况
263	  GE_ASSERT_SUCCESS(GetMapFromQueId2LoadId(impl_graph, loads_with_same_queid));
264	  for (const auto &node : impl_graph.GetAllNodes()) {
265	    GE_CHECK_NOTNULL(node);
266	    GE_CHECK_NOTNULL(node->GetOpDesc());
267	    if (num_of_load_need_adjust >= load_thresh) {
268	      GELOGD("The number of loads that need to be brought forward is %zu, which reaches threshold %zu.",
269	             num_of_load_need_adjust, load_thresh);
270	      break;
271	    }
272	    if (first_load_id == kInvalidNodeId && af::ops::IsOps<Load>(node)) {
273	      first_load_id = node->GetOpDesc()->GetId();
274	      num_of_load_need_adjust++;
275	      continue;
276	    }
277	    // 记录需要调序的input(data/workspace)和load节点：1. 非首load 2. 未被共复用 3. 和首load有公共计算节点 4.
278	    // 输出节点为非多输入节点
279	    if (first_load_id != kInvalidNodeId && af::ops::IsOps<Load>(node) && node->GetOpDesc()->GetId() > first_load_id &&
280	        loads_with_same_queid[node->outputs[0].attr.que.id].size() == 1UL &&
281	        HasSameComputeNode(dir_father_nodes, node->GetOpDesc()->GetId(), first_load_id)) {
282	      for (const auto &in_node : node->GetInAllNodes()) {
283	        GE_CHECK_NOTNULL(in_node);
284	        GE_CHECK_NOTNULL(in_node->GetOpDesc());
285	        if (ScheduleUtils::IsBuffer(std::dynamic_pointer_cast<af::AscNode>(in_node)) &&
286	            in_node->GetOpDesc()->GetId() > first_load_id) {
287	          GELOGD("Input node %s is after first load, needs to be advanced.", in_node->GetNamePtr());
288	          need_forward_nodes_id.insert(std::make_pair(in_node->GetOpDesc()->GetId(), index_data_and_load++));
289	        }
290	      }
291	      if (ScheduleUtils::IsOutNodeWithMultiInputs(node)) {
292	        continue;
293	      }
294	      GELOGD("Node %s needs to be advanced.", node->GetNamePtr());
295	      need_forward_nodes_id.insert(std::make_pair(node->GetOpDesc()->GetId(), index_data_and_load++));
296	      num_of_load_need_adjust++;
297	    }
298	  }
299	  return af::SUCCESS;
300	}
301	
302	Status DoSeqAdjustment(const af::AscGraph &impl_graph, const std::map<int64_t, int64_t> &need_forward_nodes_id,
303	                       const int64_t &first_load_id) {
304	  const size_t need_forward_nodes_num = need_forward_nodes_id.size();
305	  if (need_forward_nodes_num <= 0UL || first_load_id == kInvalidNodeId) {
306	    return af::SUCCESS;
307	  }
308	  int64_t start_index_other_nodes = first_load_id + static_cast<int64_t>(need_forward_nodes_num) + 1;
309	  for (const auto &node : impl_graph.GetAllNodes()) {
310	    GE_CHECK_NOTNULL(node);
311	    GE_CHECK_NOTNULL(node->GetOpDesc());
312	    if (node->GetOpDesc()->GetId() <= first_load_id) {
313	      continue;
314	    }
315	    if (node->GetOpDesc()->GetId() > need_forward_nodes_id.rbegin()->first) {
316	      GELOGD("No need to adjust node after node %" PRId64 ".", need_forward_nodes_id.rbegin()->first);
317	      break;
318	    }
319	    if (need_forward_nodes_id.find(node->GetOpDesc()->GetId()) != need_forward_nodes_id.end()) {
320	      GELOGD("Move node with id %" PRId64 " and name %s forward.", node->GetOpDesc()->GetId(), node->GetNamePtr());
321	      node->GetOpDesc()->SetId(first_load_id + need_forward_nodes_id.at(node->GetOpDesc()->GetId()) + 1);
322	      continue;
323	    }
324	    node->GetOpDesc()->SetId(start_index_other_nodes++);
325	  }
326	  return af::SUCCESS;
327	}
