364	bool CanDoReMergeAxis(const af::AscGraph &impl_graph, ReduceTemplateType reduce_type) {
365	  GraphPropertiesCache cache(impl_graph);
366	  // 如果包含Gather、Cube类型节点，则不能重新合并轴
367	  // RCore类型中包含Reduce的图依赖固定的二维调度轴，不能重新合并轴
368	  const bool is_rcore_reduce = (reduce_type == ReduceTemplateType::kRCore) && cache.HasReduce();
369	  return !is_rcore_reduce && !cache.HasGather() && !cache.HasCube();
