372	void FilterComplexTilingDataScoreFuncs(std::vector<::ascir::ScheduledResult> &scheduled_results,
373	                                       const std::set<std::string> &scored_graph_names) {
374	  // 如果没有需要清理的图名，直接返回
375	  if (scored_graph_names.empty()) {
376	    return;
377	  }
378	  // 只为单result单group场景注册打分函数
379	  if (scheduled_results.size() == 1UL && scheduled_results[0].schedule_groups.size() == 1UL) {
380	    GELOGD("Autoschedule score func for graph simple tiling data: %zu results, %zu groups", scheduled_results.size(),
381	           scheduled_results[0].schedule_groups.size());
382	    return;
383	  }
384	
385	  for (auto &result : scheduled_results) {
386	    for (auto &group : result.schedule_groups) {
387	      // 遍历 score_funcs，检查是否在 scored_graph_names 中
388	      auto it = group.graph_name_to_score_funcs.begin();
389	      while (it != group.graph_name_to_score_funcs.end()) {
390	        if (scored_graph_names.count(it->first) == 0) {
391	          ++it;
392	          continue;
393	        }
394	        // 只删除在 scored_graph_names 中的打分函数
395	        GELOGD("Clear autoschedule score func for graph [%s] in complex tiling data: %zu results, %zu groups",
396	               it->first.c_str(), scheduled_results.size(), result.schedule_groups.size());
397	        it = group.graph_name_to_score_funcs.erase(it);
398	      }
399	    }
400	  }
401	}
