403	Status CheckGraphValidity(const af::AscGraph &graph) {
404	  for (const auto &node : graph.GetAllNodes()) {
405	    if (ScheduleUtils::IsBuffer(node)) {
406	      continue;
407	    }
408	    for (size_t i = 0UL; i < node->outputs().size(); ++i) {
409	      const auto &tensor = node->outputs[i];
410	      const auto &axis = tensor.attr.axis;
411	      const auto &repeats = tensor.attr.repeats;
412	      const auto &strides = tensor.attr.strides;
413	      GE_ASSERT_TRUE(axis.size() == repeats.size() && repeats.size() == strides.size(),
414	                     "Output tensor[%zu] of node [%s] has mismatched sizes: axis=%zu, repeat=%zu, stride=%zu.", i,
415	                     node->GetNamePtr(), axis.size(), repeats.size(), strides.size());
416	    }
417	  }
418	  return af::SUCCESS;
419	}
