432	bool IsDanglingInputNode(const af::NodePtr &node) {
433	  if (node == nullptr || (!IsOps<Data>(node) && !IsOps<ScalarData>(node))) {
434	    return false;
435	  }
436	  return node->GetOutDataNodesSize() == 0U && node->GetOutControlNodesSize() == 0U;
437	}
