451	Status LinkDanglingInputNodesToOutput(const af::ComputeGraphPtr &graph) {
452	  GE_ASSERT_NOTNULL(graph);
453	  std::vector<af::NodePtr> output_nodes;
454	  GE_CHK_STATUS_RET(GetOutputNodes(graph, output_nodes), "Get output nodes failed, graph:[%s].",
455	                    graph->GetName().c_str());
456	  if (output_nodes.empty()) {
457	    GELOGW("Graph [%s] does not contain valid output nodes, skip linking dangling input nodes.",
458	           graph->GetName().c_str());
459	    return af::SUCCESS;
460	  }
461	  const auto &first_output_node = output_nodes.front();
462	  for (const auto &node : graph->GetDirectNode()) {
463	    GE_ASSERT_NOTNULL(node);
464	    if (!IsDanglingInputNode(node)) {
465	      continue;
466	    }
467	    // Data/ScalarData保留输入签名，通过控制边挂到输出节点避免完全悬空
468	    GE_ASSERT_GRAPH_SUCCESS(
469	        af::GraphUtils::AddEdge(node->GetOutControlAnchor(), first_output_node->GetInControlAnchor()));
470	    GELOGD("Add extra control edge between input node[%s] and output node[%s] in graph[%s].", node->GetNamePtr(),
471	           first_output_node->GetNamePtr(), graph->GetName().c_str());
472	  }
473	  return af::SUCCESS;
474	}
475	
476	Status RemoveDanglingNodes(const af::ComputeGraphPtr &graph) {
477	  GE_ASSERT_NOTNULL(graph);
478	  size_t total_removed = 0UL;
479	  bool has_removed = false;
480	  do {
481	    has_removed = false;
482	    std::vector<af::NodePtr> nodes_to_remove;
483	    // 先收集再删除，避免遍历过程中修改图节点容器
484	    for (const auto &node : graph->GetDirectNode()) {
485	      GE_ASSERT_NOTNULL(node);
486	      if (IsRemovableDanglingNode(node)) {
487	        nodes_to_remove.push_back(node);
488	      }
489	    }
490	    for (const auto &node : nodes_to_remove) {
491	      GELOGW("Remove dangling node [%s], type [%s], graph [%s].", node->GetNamePtr(), node->GetTypePtr(),
492	             graph->GetName().c_str());
493	      GE_ASSERT_GRAPH_SUCCESS(graph->RemoveNode(node));
494	      ++total_removed;
495	      has_removed = true;
496	    }
497	    // 删除末端节点后，上游节点可能变成新的无消费者节点
498	  } while (has_removed);
499	  GELOGI("Remove dangling nodes end, graph [%s], removed node num [%zu].", graph->GetName().c_str(), total_removed);
500	  return af::SUCCESS;
501	}
502	
503	Status RemoveDanglingNodes(af::AscGraph &graph) {
504	  auto compute_graph = af::AscGraphUtils::GetComputeGraph(graph);
505	  GE_ASSERT_NOTNULL(compute_graph);
506	  GE_CHK_STATUS_RET(RemoveDanglingNodes(compute_graph), "Remove dangling nodes failed, graph:[%s].",
507	                    graph.GetName().c_str());
508	  for (const auto &node : compute_graph->GetDirectNode()) {
509	    GE_ASSERT_NOTNULL(node);
510	    if (node->GetType() == "Unsupported") {
511	      const auto *error_msg = af::AttrUtils::GetStr(node->GetOpDescBarePtr(), "error_msg");
512	      GELOGE(af::FAILED, "Graph [%s] contains UnSupported node [%s]: %s", graph.GetName().c_str(), node->GetNamePtr(),
513	             error_msg != nullptr ? error_msg->c_str() : "unknown reason");
514	      return af::FAILED;
515	    }
516	  }
517	  GE_CHK_STATUS_RET(LinkDanglingInputNodesToOutput(compute_graph), "Link dangling input nodes failed, graph:[%s].",
518	                    graph.GetName().c_str());
519	  GE_ASSERT_GRAPH_SUCCESS(ScheduleUtils::TopologicalSorting(graph));
520	  return af::SUCCESS;
521	}
