1028	static Status ProcessNonReduceSchedules(const std::vector<autoschedule::AutoScheduleOutput> &schedule_outputs,
1029	                                        std::vector<ascir::ScheduledResult> &scheduled_results_cur,
1030	                                        ScheduleTask &schedule_task, std::set<std::string> &scored_graph_names) {
1031	  ScheduleGroup schedule_group;
1032	  schedule_group.impl_graphs.reserve(schedule_outputs.size());
1033	  for (const auto &schedule_output : schedule_outputs) {
1034	    schedule_group.impl_graphs.emplace_back(schedule_output.scheduled_graph);
1035	    // 目前仅对elewise+brc/单group/单result开放nddma模板打分，单result单group场景过滤放在FilterComplexTilingDataScoreFuncs
1036	    // transpose/split/concat有场景触发转为Load/Store
1037	    std::string autoschedule_graph_name =
1038	        RegisterScoreFuncInScheduleGroup(schedule_output, schedule_group, schedule_task.has_load_store_conversion);
1039	    scored_graph_names.insert(autoschedule_graph_name);
1040	  }
1041	  for (auto &res : scheduled_results_cur) {
1042	    res.schedule_groups.emplace_back(schedule_group);
1043	  }
1044	  return af::SUCCESS;
1045	}
