1057	Status Optimizer::AutoScheduler([[maybe_unused]] const HintGraph &hint_graph, ScheduleTask &schedule_task,
1058	                                std::vector<ascir::ScheduledResult> &scheduled_results) const {
1059	  size_t index = 0UL;
1060	  std::vector<ascir::ScheduledResult> scheduled_results_cur;
1061	  GE_ASSERT_SUCCESS(InitializeScheduledResults(scheduled_results_cur, schedule_task));
1062	
1063	  // 记录注册打分函数的nddma模板名
1064	  std::set<std::string> scored_graph_names;
1065	
1066	  for (auto &grouped_graph : schedule_task.grouped_graphs) {
1067	    GE_CHK_STATUS_RET(AscGraphInfoComplete::CompleteApiInfo(grouped_graph), "CompleteApiInfo failed");
1068	    if (CanDoReMergeAxis(grouped_graph, schedule_task.reduce_type)) {
1069	      GE_ASSERT_SUCCESS(RemoveAllZeroStrideLoopAxis(grouped_graph), "Remove All zero stride axis failed.");
1070	      GE_ASSERT_SUCCESS(MergeContinuousAxis(grouped_graph, schedule_task.cube_type), "Merge continuous axes failed.");
1071	    }
1072	    // 图上全部原子符号加到size var上用于生成tiling data
1073	    GE_ASSERT_SUCCESS(ScheduleUtils::ClearAllSizeVar(grouped_graph));
1074	    SizeVarSet original_var_set;
1075	    AscGraphInfoComplete::AppendOriginalSizeVar(grouped_graph, original_var_set);
1076	    for (const auto &exp : original_var_set) {
1077	      GE_ASSERT_GRAPH_SUCCESS(grouped_graph.CreateSizeVar(exp));
1078	    }
1079	    ascir::utils::DumpGraph(grouped_graph, "BeforeAutoSchedule");
1080	    GELOGI("AutoScheduler start: %s", grouped_graph.GetName().c_str());
1081	    if (ScheduleUtils::HasComputeType(grouped_graph, af::ComputeType::kComputeCube)) {
1082	      GE_ASSERT_SUCCESS(ProcessCubeSchedules(scheduled_results_cur, grouped_graph));
1083	      continue;
1084	    }
1085	    bool is_reduce_first_stage = IsReduceFirstStage(index, schedule_task);
1086	    std::vector<autoschedule::AutoScheduleOutput> schedule_outputs;
1087	    auto scheduler = autoschedule::AutoSchedule(grouped_graph, schedule_outputs, is_reduce_first_stage,
1088	                                                schedule_task.reduce_type, schedule_task.cube_type);
1089	    GE_CHK_STATUS_RET(scheduler.DoAutoSchedule(), "Failed to do schedule, graph:[%s].",
1090	                      grouped_graph.GetName().c_str());
1091	    GE_ASSERT_TRUE(!schedule_outputs.empty(), "Failed to gen tiling case for graph:[%s].",
1092	                   grouped_graph.GetName().c_str());
1093	    GELOGI("AutoScheduler end: %s, number of tiling cases = %zu", grouped_graph.GetName().c_str(),
1094	           schedule_outputs.size());
1095	    if (is_reduce_first_stage) {
1096	      GE_ASSERT_SUCCESS(ExpandReduceFirstStageResults(schedule_outputs, scheduled_results_cur, index, schedule_task));
1097	    } else {
1098	      if (schedule_task.reduce_type == ReduceTemplateType::kRCore) {
1099	        GE_ASSERT_SUCCESS(CopyImplGraphs(schedule_outputs, scheduled_results_cur));
1100	      } else {
1101	        GE_ASSERT_SUCCESS(
1102	            ProcessNonReduceSchedules(schedule_outputs, scheduled_results_cur, schedule_task, scored_graph_names));
1103	      }
1104	    }
1105	    index++;
1106	  }
1107	  scheduled_results.insert(scheduled_results.end(), scheduled_results_cur.begin(), scheduled_results_cur.end());
1108	
1109	  // 过滤复杂tilingdata的nddma打分函数
1110	  FilterComplexTilingDataScoreFuncs(scheduled_results, scored_graph_names);
1111	
1112	  return af::SUCCESS;
1113	}
