1115	void Optimizer::TryEnableGroupParallel(FusedScheduledResult &fused_scheduled_result) {
1116	  if (fused_scheduled_result.node_idx_to_scheduled_results.size() == 1UL &&
1117	      fused_scheduled_result.workspace_nodes.empty()) {  // 有workspace表示有依赖，不能使能enable_group_parallel
1118	    for (auto &schedule_result : fused_scheduled_result.node_idx_to_scheduled_results.front()) {
1119	      if (schedule_result.cube_type == CubeTemplateType::kCommon) {
1120	        schedule_result.enable_group_parallel = false;
1121	        return;
1122	      }
1123	      schedule_result.enable_group_parallel =
1124	          schedule_result.schedule_groups.size() > 1UL && schedule_result.var_relations.empty();
1125	    }
1126	  }
1127	}
